document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("derivative-form"),t=document.getElementById("derivative-result");e&&e.addEventListener("submit",function(e){e.preventDefault();let n=document.getElementById("input-expression").value.trim();n=n.replace(/\bln\(/g,"log(").replace(/\be\^/g,"exp(").replace(/exp\(([^()]+)\)/g,"e^($1)");try{const e=math.parse(n),r=math.derivative(e,"x");t.innerHTML=`<b>Derivative:</b> ${r.toString()}`}catch(e){t.innerHTML='<span style="color: red">Error: invalid expression or syntax.</span>'}})});